/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
# Track moving bbox per frame using diff with previous frame
for t in range(0,96,4):
    if t==0:
        diff = np.abs(d[1]-d[0]).sum(axis=2)
    else:
        diff = np.abs(d[t]-d[t-1]).sum(axis=2)
    ys,xs = np.where(diff>30)
    if len(xs):
        print(t, 'n=%d'%len(xs), 'x[%d,%d]'%(xs.min(),xs.max()), 'y[%d,%d]'%(ys.min(),ys.max()), 'cx=%.1f cy=%.1f'%(xs.mean(),ys.mean()))
    else:
        print(t,'none')
\""
